+    const COutPoint anchor_outpoint{anchor_parent.GetHash(), 0};
+    BOOST_CHECK(!InputIsMine(*wallet, CTxIn{anchor_outpoint}));
+
+    CWalletTx anchor_wtx{make_wtx({anchor_outpoint})};
+    BOOST_CHECK(CachedTxGetInputOwnership(*wallet, anchor_wtx) == WalletTxInputOwnership::NONE);
+
+    CWalletTx mixed_anchor_wtx{make_wtx({mine_outpoint, anchor_outpoint})};
+    BOOST_CHECK(CachedTxGetInputOwnership(*wallet, mixed_anchor_wtx) == WalletTxInputOwnership::PARTIAL);
+
+    // The classification is cached and invalidated by MarkDirty().
+    BOOST_CHECK(partial_wtx.m_cached_input_ownership.has_value());
+    partial_wtx.MarkDirty();
+    BOOST_CHECK(!partial_wtx.m_cached_input_ownership.has_value());
+    BOOST_CHECK(CachedTxGetInputOwnership(*wallet, partial_wtx) == WalletTxInputOwnership::PARTIAL);
