+    BOOST_CHECK(partial_wtx.m_cached_foreign_inputs_zero_value.has_value());
+    BOOST_CHECK_EQUAL(partial_wtx.m_cached_foreign_inputs_zero_value.value(), false);
+    partial_wtx.MarkDirty();
+    BOOST_CHECK(!partial_wtx.m_cached_foreign_inputs_zero_value.has_value());
